// 1) AES-256-GCM 字段加密：每条记录独立随机 IV，密文 = IV || ciphertext || tag
public byte[] encryptField(byte[] plaintext, SecretKey key) throws Exception {
    byte[] iv = new byte[12];                  // GCM 推荐 12 字节
    SecureRandom.getInstanceStrong().nextBytes(iv);
    Cipher c = Cipher.getInstance("AES/GCM/NoPadding");
    c.init(Cipher.ENCRYPT_MODE, key, new GCMParameterSpec(128, iv));
    byte[] ct = c.doFinal(plaintext);          // 末尾 16B 是认证 tag
    return ByteBuffer.allocate(iv.length + ct.length).put(iv).put(ct).array();
}

// 2) HMAC-SHA256 接口签名：canonical string 顺序固定
public String sign(String method, String path, Map<String,String> query,
                   byte[] body, long ts, String nonce, String keyId, byte[] secret) {
    String sortedQuery = query.entrySet().stream()
        .sorted(Map.Entry.comparingByKey())
        .map(e -> urlEncode(e.getKey()) + "=" + urlEncode(e.getValue()))
        .collect(Collectors.joining("&"));
    String bodyDigest = sha256Hex(body);       // 不直接把 body 放进签名，太大
    String canonical = String.join("\n",
        method, path, sortedQuery, bodyDigest,
        String.valueOf(ts), nonce, keyId);     // 缺一个字段都能被绕过
    Mac mac = Mac.getInstance("HmacSHA256");
    mac.init(new SecretKeySpec(secret, "HmacSHA256"));
    return Hex.encodeHexString(mac.doFinal(canonical.getBytes(StandardCharsets.UTF_8)));
}

// 3) 服务端校验：时间窗口 + nonce 去重 + 重算签名
public void verify(Request req) {
    if (Math.abs(now() - req.ts) > 300_000) throw new ReplayException("ts skew");
    if (!redis.setIfAbsent("nonce:" + req.nonce, "1", Duration.ofMinutes(5)))
        throw new ReplayException("nonce reused");
    String expect = sign(req.method, req.path, req.query, req.body,
                          req.ts, req.nonce, req.keyId, lookupSecret(req.keyId));
    if (!MessageDigest.isEqual(expect.getBytes(), req.sig.getBytes())) // 防时序攻击
        throw new SignatureException("sig mismatch");
}
